"""Builds the delivery report (Markdown) that a program owner would send to a customer."""
from pathlib import Path

from .evaluate import evaluate, load_submissions, summarize
from .key import cross_check, key_is_current
from .metrics import compute, load_config, load_log
from .reference import REGISTRY
from .tasks import load_key, load_tasks, spec_problems

BANNER = (
    "> **SYNTHETIC DEMO DATA.** The model answers and the workflow log in this report were "
    "generated by `scripts/generate_demo_data.py`. They are not results of a real program."
)


def _percent(value):
    return f"{value * 100:.1f}%"


def build_report(root, submission_files, log_path, config_path):
    tasks, key = load_tasks(), load_key()
    config = load_config(config_path)
    metrics = compute(load_log(log_path), config)
    rows = cross_check()
    problems = spec_problems(tasks)

    lines = [f"# Delivery report: {config['program']}", "", BANNER, ""]

    lines += ["## 1. Task quality gate", ""]
    agree = sum(1 for row in rows if row[4])
    lines += [
        f"- Tasks in the benchmark: **{len(tasks)}**",
        f"- Tasks where two independent reference solutions agree: **{agree}/{len(rows)}**",
        f"- Specification problems: **{len(problems)}**",
        f"- Answer key matches the reference solutions: **{'yes' if key_is_current() else 'NO'}**",
        "",
        "| Task | Solution A | Solution B | Must agree within | Result |",
        "|---|---|---|---|---|",
    ]
    for task_id, a, b, _, ok in rows:
        tolerance = REGISTRY[task_id].cross_check_rel_tol
        lines.append(f"| {task_id} | {a:.8g} | {b:.8g} | {tolerance:.0e} | {'agree' if ok else 'FAIL'} |")

    lines += ["", "## 2. Model evaluation", ""]
    for path in submission_files:
        model, answers = load_submissions(path)
        summary = summarize(evaluate(answers, tasks, key))
        lines += [
            f"### {model}", "",
            f"- Accuracy: **{_percent(summary['accuracy'])}** "
            f"({summary['outcomes']['correct']}/{summary['total']})",
            "- Outcomes: " + ", ".join(f"{name} {count}" for name, count in summary["outcomes"].items()),
            "- By domain: " + ", ".join(
                f"{name} {_percent(acc)}" for name, (acc, _) in summary["by_domain"].items()),
            "- By difficulty: " + ", ".join(
                f"{name} {_percent(acc)}" for name, (acc, _) in summary["by_difficulty"].items()),
            "",
        ]

    lines += [
        "## 3. Production metrics", "",
        "| Metric | Value | Target | Status |", "|---|---|---|---|",
        f"| First-pass acceptance rate | {_percent(metrics['first_pass_rate'])} | "
        f"{_percent(config['first_pass_target'])} | {metrics['first_pass_status']} |",
        f"| Review turnaround, 90th percentile | {metrics['turnaround_p90_hours']:.1f} h | "
        f"{config['turnaround_p90_sla_hours']} h | {metrics['turnaround_status']} |",
        f"| Review turnaround, median | {metrics['turnaround_median_hours']:.1f} h | - | - |",
        f"| Rework rate | {_percent(metrics['rework_rate'])} | - | - |",
        "",
        f"Tasks submitted {metrics['submitted']}, accepted {metrics['accepted']}, "
        f"rejected {metrics['rejected']}, still in review {metrics['in_review']}.",
        "",
        f"Weekly accepted tasks (target {config['weekly_accepted_target']}; the last week is "
        "partial and has no status):", "",
        "| Week | Accepted | Status |", "|---|---|---|",
    ]
    for week, count in metrics["weekly_accepted"].items():
        lines.append(f"| {week} | {count} | {metrics['weekly_status'].get(week, 'partial week')} |")

    lines += ["", "### Quality by contributor (lowest first)", "",
              "| Contributor | Reviewed | First-pass rate | Status |", "|---|---|---|---|"]
    for item in metrics["contributors"]:
        lines.append(
            f"| {item['contributor']} | {item['reviewed']} | "
            f"{_percent(item['first_pass_rate'])} | {item['status']} |")
    lines += ["", "### Review speed by reviewer (median hours to first review)", "",
              "| Reviewer | Median hours |", "|---|---|"]
    for name, hours in metrics["reviewer_median_hours"].items():
        lines.append(f"| {name} | {hours:.1f} |")

    lines += [
        "", "## 4. Actions a program owner would take from this data", "",
        "- Contributors with a RED first-pass rate get coaching and closer review of new tasks.",
        "- A reviewer with a far higher median turnaround is the bottleneck: rebalance the queue.",
        "- Weeks below target: check intake, reviewer capacity and rework before adding contributors.",
        "- See `docs/05-risk-register.md` for risks and `docs/04-metrics-and-sla.md` for definitions.",
        "",
    ]
    return "\n".join(lines)


def write_report(root, submission_files, log_path, config_path):
    text = build_report(root, submission_files, log_path, config_path)
    out = Path(root) / "reports" / "delivery_report.md"
    out.parent.mkdir(exist_ok=True)
    out.write_text(text, encoding="utf-8")
    return out
